        {
          "id": "C-INTEGRITY",
          "kind": "EXECUTION_PRECONDITION_NOT_RUN",
          "condition": "Alle Tabellen sind manuelle Fachvorschlaege unter den bestehenden Integritaetsanforderungen. Ein tatsaechlich nachgewiesener Parser-/Struktur-/Bindungs-/Referenz-/Weltfehler verhindert jeden fachlichen Bericht und wird durch keine Invalidierung oder korrekte Antwort geheilt."
        },
        {
          "id": "C-POLICY",
          "kind": "FUTURE_NORMATIVE_ADOPTION_REQUIRED",
          "condition": "Nicht-vakuose Totalisierung und Kontextpraezisierung benoetigen einen eigenen exakten Ganztext samt erforderlichen fremden Ganztextvoten. Keine Empfehlung hier angenommen."
        },
        {
          "id": "C-U07",
          "kind": "INDEPENDENT_SPECIFICATION_PENDING",
          "condition": "Die getrennte U07-Arbeit muss ihre revisionsgebundene Qualifikation der unbeschraenkten Lueckenlesart und des referenzierten App-Undo liefern. Falls keine Integritaetssperre besteht, gelten die hier vorgeschlagenen Fachwerte/Claimentscheidungen bedingt; daraus folgt kein finaler U07- oder Gesamtoracleentscheid. Keine Grenze verborgener Aktionen aus einer fehlenden seq. Historische INCONCLUSIVE-Qualifikation bleibt erhalten."
        },
        {
          "id": "C-INTEGRATION",
          "kind": "FUTURE_COMPLETE_MANIFEST_GATE",
          "condition": "Neue vollstaendige Katalog-/Vertrags-/Regel-/Fallfassung, Beleg-/Wortlautbindung, externe Pflichtinventur und Zusatzgateintegration, gesamter Freeze und Fremdpruefung bleiben erforderlich. Keine Implementation aus diesem Dokument."
        }
      ]
    },
    {
      "source": {
        "path": "F:/ChnobelRuntime/reviews/v2-manifest-questions-04/guard/architekt/decision.json",
        "sha256": "210416ca127b089919c0fff785d7677e3f7b82a44d8176cb9b28af7df240bccb",
