      },
      "pointer": "/totalisationRule",
      "fields": [
        "*"
      ],
      "originalValue": {
        "status": "PROPOSED_NOT_ACCEPTED",
        "priorities": [
          {
            "priority": 0,
            "rule": "Parser-/Struktur-/Bindungs-/Referenz-/Weltintegritaet vor jeder fachlichen Bewertung. Nachgewiesener Fehler: Fehlerbericht ohne Fakten/Claims. Alle solchen Ausfuehrungen hier NOT_RUN.",
            "sources": [
              "ADR 0003 D4.1",
              "CONTRACT §2/§6",
              "error-catalogue.json /stageOrder"
            ]
          },
          {
            "priority": 1,
            "rule": "Offene Norm-/Vertragsentscheidung als SPECIFICATION_PENDING mit benannter Bedingung fuehren; niemals durch Domaenenwert unbekannt oder bestandenes Enthaltungsoracle ersetzen."
          },
          {
            "priority": 2,
            "rule": "Tatsaechliche notwendige gemeinsame Kontextabhaengigkeiten in jeder Kette mitpruefen. Expliziter Kontextveto macht jeden abhaengigen Guard falsch und kann nicht durch lokale Alternativen umgangen werden. Fehlende Abgabe ist unbekannt, nicht Invalidierung."
          },
          {
            "priority": 3,
            "rule": "Ketten/Zertifikate fuer denselben verwendeten Fachwert explizit benennen: positiver Leistungsbeleg, gueltiger negativer Beobachtungsbeleg oder vollstaendige gueltige Beobachtung mit fachlich begrenzter Unentscheidbarkeit. Kein positives Ergebnis allein aus deren Gueltigkeit."
          },
          {
            "priority": 4,
            "rule": "Innerhalb einer Kette: notwendiger explizit invalidierter Beleg ist falsch; sonst fehlende/unsichere notwendige Abhaengigkeit unbekannt; sonst wahr. Positive Hilfe/negative Kanalabdeckung bleiben in den zugehoerigen Hilfefakten, damit nicht benoetigte Hilfequalifikation unabhaengige Darstellung unterdrueckt."
          },
          {
            "priority": 5,
            "rule": "Zwischen benannten passenden Alternativen: eigenstaendig vollstaendig gueltige Kette genuegt; bei keiner solchen und mindestens einer erforderlichen ungesicherten Alternative unbekannt; bei nichtleerer ausschliesslich nachweislich invalidierter Menge falsch. Leere Menge unbekannt. Keine bloss denkbare Zukunft oder erfundene versteckte Ereignisse als Alternative. Negative Zertifikate duerfen unsichere fruehere Positivbelege nicht als sicher abwesend ausgeben."
          },
          {
            "priority": 6,
            "rule": "Fachwert, Gueltigkeit und (historische) Hilfequalifikation kohaerent an dieselben konkreten Belege binden; kein Mischen eines gueltigen fremden Ankers mit einer invalidierten positiven Behauptung."
          },
          {
            "priority": 7,
            "rule": "Jede Regel wendet ihre eigenen all/none-Anforderungen an: bewiesenes falsches all oder wahres none -> must_not_claim; sonst unbekannte benoetigte Fakten -> undecidable; sonst must_claim. Fehlende Anwendbarkeit bleibt undecidable. Fallback erneut durch eigene Regel. Diese Beschreibung wurde nicht als Auswertungsengine implementiert."
          }
        ],
        "absentResultVsObservedNegative": "Leere Antwortkette bleibt proof.result.valid=unbekannt; gueltiger Anfang mit vollstaendig beobachtetem Verlauf ohne Kindhandlung kann Material-/Historien-Negativzertifikate tragen. Fehlender positiver Weg allein setzt einen Guard nicht unbekannt.",
        "validObservationOfUnknown": "Vollstaendig bekanntes nicht katalogisiertes Kindlayout kann proof.path.valid=wahr und board.path.child=unbekannt tragen. Anders U07: notwendige Materialkette selbst unvollstaendig, deshalb Guard unbekannt.",
        "existingPolicyNotOverridden": [
          "D1 Handlung/Material/Hilfe/Undo getrennt",
          "D2 keine Ein-Slot-Obergrenze; frische Antwort erneuert nur eigene Kette",
          "D3 keine negative Kompetenzdiagnose aus unvollstaendigem Musterkatalog",
          "D4 Invalidierung kein Undo; Alternativen nur eigenstaendig gueltig",
          "D5 negative Hilfefakten nicht aus fehlenden Events allein"
        ]
      }
    },
