            "attempt.opened Aufgabenbindung",
            "attempt.closed Abgabebindung",
            "answer.committed und aktuelle Aktivitaet",
            "input.captured",
            "recognition.proposed nur wenn erforderlich",
            "einschlaegige Invalidierung/Lifecycle"
          ],
          "sources": [
